#include "serialconfigeditor.h"

#include <QComboBox>
#include <QLineEdit>
#include <QPushButton>
#include <QSerialPortInfo>

#include "ui_serialconfigeditor.h"   // generated by uic from serialconfigeditor.ui

SerialConfigEditor::SerialConfigEditor(QWidget *parent) : iwp::FormConfigEditor(parent)
{
    // The layout, labels and the lists of choices are in serialconfigeditor.ui. Here: the list of
    // ports (it depends on what is plugged in) and the keys of the config.
    auto *page = new QWidget;
    Ui::SerialConfigEditor ui;
    ui.setupUi(page);
    setupPage(page);

    m_port = ui.portCombo;
    m_port->lineEdit()->setPlaceholderText(tr("no ports found"));
    refreshPorts();
    bindCombo(QStringLiteral("port"), m_port);
    connect(ui.refreshButton, &QPushButton::clicked, this, &SerialConfigEditor::refreshPorts);

    // The values stored in the config, in the same order as the items in the .ui.
    bindComboValues(QStringLiteral("baud"), ui.baudCombo,
                    {1200, 2400, 4800, 9600, 19200, 38400, 57600, 115200, 230400, 460800, 921600, 1000000});
    bindComboValues(QStringLiteral("dataBits"), ui.dataBitsCombo, {5, 6, 7, 8});
    bindComboValues(QStringLiteral("parity"), ui.parityCombo,
                    {QStringLiteral("none"), QStringLiteral("even"), QStringLiteral("odd"),
                     QStringLiteral("space"), QStringLiteral("mark")});
    bindComboValues(QStringLiteral("stopBits"), ui.stopBitsCombo,
                    {QStringLiteral("1"), QStringLiteral("1.5"), QStringLiteral("2")});
    bindComboValues(QStringLiteral("flow"), ui.flowCombo,
                    {QStringLiteral("none"), QStringLiteral("hardware"), QStringLiteral("software")});
}

void SerialConfigEditor::refreshPorts()
{
    // what is selected or typed now (the port may have been unplugged meanwhile)
    const int i = m_port->currentIndex();
    const QString text = m_port->currentText().trimmed();
    const QString keep = (i >= 0 && text == m_port->itemText(i)) ? m_port->itemData(i).toString() : text;

    m_port->clear();
    for (const QSerialPortInfo &info : QSerialPortInfo::availablePorts()) {
#ifdef Q_OS_MACOS
        if (info.systemLocation().startsWith(QLatin1String("/dev/tty.")))
            continue;   // on macOS the /dev/cu.* twin is the right one for outgoing connections
#endif
        const QString description = info.description();
        m_port->addItem(description.isEmpty() ? info.systemLocation()
                                              : info.systemLocation() + QStringLiteral(" - ") + description,
                        info.systemLocation());
    }
    if (keep.isEmpty())
        return;
    const int idx = m_port->findData(keep);
    if (idx >= 0)
        m_port->setCurrentIndex(idx);
    else
        m_port->setEditText(keep);
}

QString SerialConfigEditor::validate() const
{
    return config().value(QStringLiteral("port")).toString().trimmed().isEmpty()
               ? tr("Select a serial port") : QString();
}
